ALTER TABLE public.document_outputs ADD COLUMN phase2_quarantined boolean NOT NULL DEFAULT false;
ALTER TABLE public.document_outputs ADD COLUMN phase2_gate jsonb;
UPDATE public.document_outputs o SET phase2_quarantined=true, phase2_gate=jsonb_build_object('decision','excluded','phase','Phase 3','reason','Missing persisted draft/classification/source manifest or empty legacy set; source binding not established. Preserve original JSON.','at',now(),'authority','Owner-authorized Phase 2 remediation 2026-10-22','before_sha256',encode(sha256(convert_to(o.outputs::text,'UTF8')),'hex'),'classification','unestablished','approval','not established','verifiedCoverage',false)
WHERE jsonb_array_length(CASE WHEN jsonb_typeof(o.outputs->'outputs')='array' THEN o.outputs->'outputs' ELSE '[]'::jsonb END)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.outputs->'outputs')='array' THEN o.outputs->'outputs' ELSE '[]'::jsonb END) x WHERE coalesce(x->'manifest'->>'approval','')<>'draft' OR coalesce(x->'manifest'->>'classification','') NOT IN ('DEMO','unverified') OR coalesce(x->'manifest'->>'jobId','')='');
INSERT INTO public.audit_events(actor_id,organization_id,event,outcome,details) SELECT NULL,organization_id,'output.phase2_quarantined','success',jsonb_build_object('set_id',id,'document_id',document_id,'source_hash',source_hash,'source_version',source_version,'original_outputs_sha256',encode(sha256(convert_to(outputs::text,'UTF8')),'hex'),'gate',phase2_gate,'actor','Owner-authorized schema backfill; no impersonated user') FROM public.document_outputs WHERE phase2_quarantined;
CREATE OR REPLACE FUNCTION public.enforce_output_draft_manifest() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='UPDATE' AND OLD.phase2_quarantined THEN RAISE EXCEPTION 'Quarantined historical output is immutable'; END IF;
 IF NEW.phase2_quarantined OR NEW.phase2_gate IS NOT NULL THEN RAISE EXCEPTION 'Output gate changes require separately authorized remediation'; END IF;
 IF jsonb_typeof(NEW.outputs->'outputs') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.outputs->'outputs')=0 THEN RAISE EXCEPTION 'Nonempty draft output set required'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.outputs->'outputs') x WHERE coalesce(x->'manifest'->>'approval','')<>'draft' OR coalesce(x->'manifest'->>'classification','') NOT IN ('DEMO','unverified') OR x->'manifest'->'verifiedCoverage' IS DISTINCT FROM 'false'::jsonb OR coalesce(x->'manifest'->>'jobId','')='' OR x->'manifest'->>'documentId' IS DISTINCT FROM NEW.document_id::text OR coalesce(x->'manifest'->>'originalHash','')='') THEN RAISE EXCEPTION 'Persisted source-linked unapproved manifest required'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER enforce_output_draft_manifest BEFORE INSERT OR UPDATE ON public.document_outputs FOR EACH ROW EXECUTE FUNCTION public.enforce_output_draft_manifest();
ALTER POLICY outputs_read ON public.document_outputs USING (public.is_member(organization_id) AND NOT phase2_quarantined);
CREATE VIEW public.phase3_output_gate WITH (security_invoker=true) AS SELECT id,organization_id,document_id,false AS eligible,'All saved outputs are draft; quarantined legacy sets are excluded by RLS. Phase 3 is not authorized.'::text AS reason FROM public.document_outputs;
GRANT SELECT ON public.phase3_output_gate TO authenticated;
GRANT SELECT ON public.phase3_output_gate TO service_role;
COMMENT ON COLUMN public.document_outputs.phase2_quarantined IS 'Persisted immutable quarantine for unsafe historical sets; ordinary RLS reads exclude them from all output consumers.';
COMMENT ON VIEW public.phase3_output_gate IS 'Fail-closed Phase 3 gate. No output eligibility granted in Phase 2; enabling requires separately authorized implementation and review.';